//======================>>> CCCanvasPane::ZoomIn <<<======================
  void CCCanvasPane::ZoomIn(int factor) 
{
  Clear();
  resizeX*=factor; 
  resizeY*=factor;   
  Redraw(0,0,0,0);
}

//======================>>> CCCanvasPane::ZoomOut <<<======================
  void CCCanvasPane::ZoomOut(int factor) 
{
  float testX, testY;
  testX=resizeX/factor;
  testY=resizeY/factor;
  if ((testX>=1)&&(testY>=1))
    {
      Clear();
      resizeX=(int)(resizeX/factor); 
      resizeY=(int)(resizeY/factor);      
    }
  Redraw(0,0,0,0);
}
